def parse(text: str) -> list[list[str]]:
    """Parse CSV text into a list of records, each a list of field strings."""
    rows = []
    i = 0
    n = len(text)

    while i < n:
        row = []
        # Parse one row (which may span multiple lines if there are embedded newlines)
        while True:
            field = ""
            # Skip leading whitespace (but not newlines)
            while i < n and text[i] in (' ', '\t'):
                i += 1

            if i < n and text[i] == '"':
                # Quoted field
                i += 1  # skip opening quote
                while i < n:
                    if text[i] == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            # Escaped quote
                            field += '"'
                            i += 2
                        else:
                            # End of quoted field
                            i += 1  # skip closing quote
                            break
                    else:
                        field += text[i]
                        i += 1
                # Skip any trailing whitespace after closing quote
                while i < n and text[i] in (' ', '\t'):
                    i += 1
                # If next char is comma or end of line, field is complete
                if i < n and text[i] == ',':
                    i += 1  # skip comma
                    row.append(field)
                else:
                    row.append(field)
                    break
            else:
                # Unquoted field - read until comma or end of line
                while i < n and text[i] != ',' and text[i] != '\n' and text[i] != '\r':
                    field += text[i]
                    i += 1
                row.append(field)
                if i < n and text[i] == ',':
                    i += 1  # skip comma
                else:
                    break

            # If we hit end of input without comma, break
            if i >= n:
                break

        # Skip line endings
        if i < n and text[i] == '\r':
            i += 1
        if i < n and text[i] == '\n':
            i += 1

        # Only add non-empty rows (but preserve rows with empty fields)
        if row or (i < n):
            # Check if this was just an empty line at the end
            if row == [''] and i >= n:
                break
            rows.append(row)

    return rows

