def parse(text: str) -> list[list[str]]:
    """Parse CSV text into a list of records, each a list of field strings."""
    rows = []
    i = 0
    n = len(text)

    while i < n:
        row, i = _parse_row(text, i, n)
        if row is not None:
            rows.append(row)

    return rows


def _parse_row(text: str, i: int, n: int) -> tuple[list[str] | None, int]:
    """Parse a single row starting at position i. Returns (fields, new_position) or (None, i) if done."""
    fields = []

    while True:
        if i >= n:
            # End of input
            if not fields:
                return None, i
            return fields, i

        ch = text[i]

        if ch == '"':
            # Quoted field
            field, i = _parse_quoted_field(text, i, n)
            fields.append(field)
        else:
            # Unquoted field - read until comma, newline, or end
            field, i = _parse_unquoted_field(text, i, n)
            fields.append(field)

        # After a field, expect comma, newline, or end of input
        if i >= n:
            return fields, i

        if text[i] == ',':
            # More fields follow
            i += 1
        elif text[i] == '\r':
            # CRLF or just CR
            i += 1
            if i < n and text[i] == '\n':
                i += 1
            return fields, i
        elif text[i] == '\n':
            i += 1
            return fields, i
        else:
            # Unexpected character after field
            i += 1


def _parse_quoted_field(text: str, i: int, n: int) -> tuple[str, int]:
    """Parse a quoted field starting with the opening quote at position i."""
    # Skip opening quote
    i += 1
    parts = []

    while i < n:
        if text[i] == '"':
            if i + 1 < n and text[i + 1] == '"':
                # Escaped quote
                parts.append('"')
                i += 2
            else:
                # End of quoted field
                i += 1
                break
        elif text[i] == '\r':
            # Handle CRLF inside quoted field as just LF
            parts.append('\n')
            i += 1
            if i < n and text[i] == '\n':
                i += 1
        elif text[i] == '\n':
            parts.append('\n')
            i += 1
        else:
            parts.append(text[i])
            i += 1

    return ''.join(parts), i


def _parse_unquoted_field(text: str, i: int, n: int) -> tuple[str, int]:
    """Parse an unquoted field starting at position i."""
    start = i
    while i < n:
        ch = text[i]
        if ch == ',':
            return text[start:i], i + 1
        elif ch == '\r':
            field = text[start:i]
            i += 1
            if i < n and text[i] == '\n':
                i += 1
            return field, i
        elif ch == '\n':
            return text[start:i], i + 1
        else:
            i += 1
    return text[start:i], i

