                            i += 2
                        else:
                            # End of quoted field
                            i += 1  # skip closing quote
                            break
                    else:
                        field.append(text[i])
                        i += 1
                row.append(''.join(field))
            else:
                # Unquoted field
                field = []
                while i < n and text[i] != ',' and text[i] != '\n' and text[i] != '\r':
                    field.append(text[i])
                    i += 1
                row.append(''.join(field))

            # After field, expect comma, newline, or end
            if i < n and text[i] == ',':
                i += 1  # skip comma, continue to next field
            else:
                # End of row (newline or end of text)
                if i < n and text[i] == '\r':
                    i += 1
                if i < n and text[i] == '\n':
                    i += 1
                break

        # Skip empty rows (from trailing newlines or blank lines)
        if row or (len(row) == 1 and row[0] == ''):
            # Only skip if truly empty (no content at all)
            if not row or (len(row) == 1 and row[0] == '' and i < n):
